import fs from 'node:fs/promises';
import path from 'node:path';
import vm from 'node:vm';
import {fileURLToPath} from 'node:url';
import {brandSlugFor} from './routing-v3.mjs';
import {CURATED_COMPARE_NAMES} from './content.mjs';
import {matchOfficialBrands} from './official-merge.mjs';
import {esc,finite,num,won,signedWon,count,pct,growthPct,growthAbs,median,percentile,qualityForOfficial,officialView,costComponents,renderStackedBar,renderLineChart,renderHorizontalBars,renderGroupedBars} from './v10-lib.mjs';

// v9.1 remains only as a route/bootstrap fallback during the migration.
// v10 rewrites all index-candidate surfaces and removes every legacy visual CSS link/output.
await import(`./run-generate-v9-1.mjs?v10=${Date.now()}`);

const here=path.dirname(fileURLToPath(import.meta.url));
const repo=path.resolve(here,'..');
const out=path.join(repo,'docs/franchise-ssg-preview');
const PREVIEW=(process.env.SSG_PREVIEW_MODE??'true')!=='false';
const BASE=(process.env.SSG_BASE_PATH??'/pm-lab/franchise-ssg-preview').replace(/\/$/,'');
const SITE=(process.env.SSG_SITE_URL??'https://5ggul.github.io/pm-lab/franchise-ssg-preview').replace(/\/$/,'');
const robots=PREVIEW?'noindex,nofollow,noarchive,nosnippet':'index,follow';
const generatedAt=new Date().toISOString();

async function loadClassic(file,expr){const code=await fs.readFile(file,'utf8');const ctx={console};vm.createContext(ctx);vm.runInContext(`${code}\n;globalThis.__EXPORT__=${expr};`,ctx);return ctx.__EXPORT__}
const catalog=await loadClassic(path.join(repo,'docs/franchise-data-preview/data-final.js'),'{categories,brands}');
const official=JSON.parse(await fs.readFile(path.join(repo,'data/franchise/official/brands-2025.json'),'utf8'));
const matched=matchOfficialBrands(catalog.brands,official);
const hitByName=new Map(matched.matches.map(x=>[x.brand.name,x]));
const views=catalog.brands.map(b=>officialView(b,hitByName.get(b.name)||null));
const byName=new Map(views.map(b=>[b.name,b]));
const bySlug=new Map(views.map(b=>[brandSlugFor(b.name,b.slug),b]));
const categoryEntries=Object.entries(catalog.categories);
const reviewDate=String(official.generatedAt||generatedAt).slice(0,10);
const priorityNames=[
  '메가MGC커피','컴포즈커피','빽다방','이디야커피','더벤티','매머드커피',
  '교촌치킨','bhc치킨','BBQ치킨','굽네치킨','네네치킨','맘스터치','프랭크버거','롯데리아',
  '김가네','얌샘김밥','신전떡볶이','청년다방','한솥','본죽&비빔밥',
  '파리바게뜨','뚜레쥬르','배스킨라빈스','설빙','CU','GS25','세븐일레븐','이마트24',
  '역전할머니맥주','생활맥주'
];
const priorityCandidates=new Set(priorityNames.filter(n=>byName.get(n)?.quality?.indexCandidate));

const url=p=>`${BASE}${p==='/'?'':p}`.replace(/\/+/g,'/');
const absolute=p=>`${SITE}${p==='/'?'':p}`;
const slugOf=b=>brandSlugFor(b.name,b.slug);
const json=x=>JSON.stringify(x).replace(/</g,'\\u003c');
const write=async(rel,html)=>{const file=path.join(out,rel,'index.html');await fs.mkdir(path.dirname(file),{recursive:true});await fs.writeFile(file,html,'utf8')};
const writeText=async(rel,text)=>{const file=path.join(out,rel);await fs.mkdir(path.dirname(file),{recursive:true});await fs.writeFile(file,text,'utf8')};

const header=`<header class="site-header"><div class="shell header-inner"><a class="logo" href="${url('/')}">창업데이터랩</a><nav aria-label="주요 메뉴"><a href="${url('/brands/')}">브랜드 찾기</a><a href="${url('/categories/')}">업종 데이터</a><a href="${url('/compare/')}">두 브랜드 비교</a><a href="${url('/tools/')}">계산기</a><a href="${url('/guide/low-price-coffee/')}">데이터 리포트</a><a href="${url('/sources/')}">데이터 출처</a></nav><button class="nav-toggle" aria-label="메뉴 열기" aria-expanded="false">메뉴</button></div></header>`;
const footer=`<footer class="site-footer"><div class="shell footer-grid"><div><strong>창업데이터랩</strong><p>공개자료를 같은 단위와 기준으로 정리해 프랜차이즈 비용·점포 변화를 비교합니다.</p></div><div><a href="${url('/about/')}">서비스 소개</a><a href="${url('/sources/')}">데이터 출처</a><a href="${url('/methodology/')}">계산 기준</a><a href="${url('/updates/')}">데이터 변경 기록</a></div><div><a href="${url('/privacy/')}">개인정보처리방침</a><a href="${url('/terms/')}">이용약관</a><a href="${url('/disclaimer/')}">면책 고지</a><a href="${url('/contact/')}">문의</a></div></div><div class="shell footer-note">공정거래위원회 또는 가맹본부의 공식 사이트가 아닙니다. 공개자료의 해석·정규화 결과이며 계약 전 최신 정보공개서와 실제 견적을 확인해야 합니다.</div></footer>`;
const crumb=(items)=>`<nav class="crumbs" aria-label="현재 위치">${items.map((x,i)=>i===items.length-1?`<span>${esc(x[0])}</span>`:`<a href="${url(x[1])}">${esc(x[0])}</a><i>›</i>`).join('')}</nav>`;
function head({title,description,canonical='/',schemas=[]}){return `<!doctype html><html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,viewport-fit=cover"><meta name="robots" content="${robots}"><meta name="googlebot" content="${robots}"><meta name="bingbot" content="${robots}"><title>${esc(title)}</title><meta name="description" content="${esc(description)}"><link rel="canonical" href="${absolute(canonical)}"><link rel="stylesheet" href="${url('/assets/site.css')}">${schemas.map(s=>`<script type="application/ld+json">${json(s)}</script>`).join('')}</head><body><div class="preview-bar">외부 검수용 프리뷰 · 검색엔진 색인 차단</div>${header}`}
const end=()=>`${footer}<script src="${url('/assets/app.js')}" defer></script></body></html>`;
const breadcrumbSchema=(items)=>({'@context':'https://schema.org','@type':'BreadcrumbList',itemListElement:items.map((x,i)=>({'@type':'ListItem',position:i+1,name:x[0],item:absolute(x[1])}))});
const orgSchema={'@context':'https://schema.org','@type':'Organization','name':'창업데이터랩','url':SITE};
const siteSchema={'@context':'https://schema.org','@type':'WebSite','name':'창업데이터랩','url':SITE,'potentialAction':{'@type':'SearchAction','target':`${SITE}/brands/?q={search_term_string}`,'query-input':'required name=search_term_string'}};
const sourceLink=()=>`<a href="https://www.data.go.kr/data/15110265/openapi.do" rel="external noopener">공공데이터포털 · 공정거래위원회 창업비용 통계</a> · <a href="https://www.data.go.kr/data/15110241/openapi.do" rel="external noopener">가맹점·매출 통계</a>`;

function peers(b){return views.filter(x=>x.categorySlug===b.categorySlug&&x.name!==b.name&&x.dataMode==='FTC_OFFICIAL')}
function catStats(slug){const rows=views.filter(b=>b.categorySlug===slug&&b.dataMode==='FTC_OFFICIAL');return {rows,cost:median(rows.map(b=>b.cost)),stores:median(rows.map(b=>b.stores)),sales:median(rows.map(b=>b.sales)),growth:median(rows.map(growthPct))}}
function dataBasis(b){return b.official?`${b.official.referenceYear} 정보공개서 공개자료 · 데이터 갱신 ${reviewDate}`:`공식 레코드 자동 매칭 보류 · 데이터 갱신 ${reviewDate}`}
function summaryText(b){
  if(!b.official)return `${b.name}은 현재 공식 레코드와의 자동 매칭이 완료되지 않았습니다. 이 페이지에서는 합성값이나 추정값으로 빈칸을 채우지 않습니다. 공식 명칭과 가맹본부가 확인될 때까지 비용·점포·매출 수치는 “정보 없음”으로 유지합니다.`;
  const s=catStats(b.categorySlug),parts=[];const cg=finite(b.cost)&&finite(s.cost)?(b.cost-s.cost)/s.cost*100:null,g=growthPct(b),abs=growthAbs(b);
  if(finite(cg))parts.push(`공개 창업비용은 같은 업종의 매칭 브랜드 중앙값보다 ${Math.abs(cg).toFixed(1)}% ${cg>=0?'높게':'낮게'} 나타납니다.`);
  if(finite(abs))parts.push(`가맹점 수는 이전 기준보다 ${Math.abs(Math.round(abs)).toLocaleString('ko-KR')}개 ${abs>=0?'늘었습니다':'줄었습니다'}.`);
  if(b.official?.storeHistory?.length>=2)parts.push(`한 해의 증감만으로 성장성이나 안정성을 단정하지 않고 연도별 점포 흐름과 신규·종료·해지를 함께 확인해야 합니다.`);
  if(finite(b.sales))parts.push(`평균매출 공개지표는 매출액 관련 공개값이며 점주의 순이익이나 소득을 뜻하지 않습니다.`);
  parts.push(`계약 전에는 공개합계에 빠질 수 있는 임대보증금·권리금·철거·전기증설·외부공사와 실제 점포 견적을 별도로 확인해야 합니다.`);
  return parts.join(' ');
}
function hiddenCostChecklist(){return `<div class="check-grid"><div class="check-item"><strong>임대보증금·권리금</strong><span>가맹본부 공개합계와 별도인 점포 계약 비용인지 확인</span></div><div class="check-item"><strong>철거·전기증설·소방</strong><span>기준 공사 범위 밖의 별도공사 항목과 단가 확인</span></div><div class="check-item"><strong>외부공사·냉난방</strong><span>파사드, 덕트, 냉난방 등 점포 조건별 공사 범위 확인</span></div><div class="check-item"><strong>초도물품·운전자금</strong><span>오픈 전 재고와 초기 적자 기간에 필요한 현금 별도 확보</span></div></div>`}
function costTable(b){const comps=costComponents(b);return `<table class="data-table stack-mobile"><thead><tr><th>항목</th><th class="num">공개금액</th><th class="num">구성비</th></tr></thead><tbody>${comps.map(c=>`<tr><td data-label="항목">${esc(c.label)}</td><td data-label="공개금액" class="num">${won(c.value)}</td><td data-label="구성비" class="num">${finite(b.cost)&&b.cost>0?`${(c.value/b.cost*100).toFixed(1)}%`:'정보 없음'}</td></tr>`).join('')}</tbody></table>`}
function brandFaq(b){const y=b.official?.referenceYear??'기준연도 미확인';const answers=[];if(finite(b.cost))answers.push([`${b.name} 창업비용은 얼마인가요?`,`${y} 공개자료 기준 창업비용 합계는 ${won(b.cost)}입니다. 임대보증금·권리금·별도공사 등 점포별 비용은 별도일 수 있습니다.`]);if(finite(b.stores))answers.push([`${b.name} 가맹점은 몇 개인가요?`,`${y} 공개자료 기준 가맹점 수는 ${count(b.stores)}입니다. 점포 수는 브랜드 규모 지표이며 개별 점포 수익을 의미하지 않습니다.`]);if(finite(growthPct(b)))answers.push([`${b.name} 가맹점은 전년보다 늘었나요?`,`이전 기준 대비 점포 변화율은 ${pct(growthPct(b))}입니다. 한 해 변화만으로 수익성이나 안정성을 판단하지 않습니다.`]);answers.push([`${b.name} 공개 창업비용이 실제 총투자금인가요?`,`아닙니다. 공개합계와 점포 임대보증금·권리금·철거·전기증설·외부공사·운전자금을 분리해서 확인해야 합니다.`]);if(finite(b.sales))answers.push([`${b.name} 평균매출 공개지표가 곧 수익인가요?`,`아닙니다. 공개 매출값은 원가·인건비·임대료·로열티·세금 등을 차감한 순이익이 아닙니다.`]);return answers.slice(0,5)}

// HOME
const officialViews=views.filter(b=>b.dataMode==='FTC_OFFICIAL');
const homeFeatured=['메가MGC커피','컴포즈커피','빽다방','교촌치킨','bhc치킨','한솥','파리바게뜨','CU'].map(n=>byName.get(n)).filter(b=>b?.official);
const categoryChartSlugs=['cafe','chicken','snack','bakery','convenience','pub'].filter(s=>catalog.categories[s]);
const categoryChartData=categoryChartSlugs.map(s=>({label:catalog.categories[s].name,value:catStats(s).cost})).filter(x=>finite(x.value));
const homeHtml=`${head({title:'프랜차이즈 창업비용·가맹점 데이터 비교 | 창업데이터랩',description:'공정거래위원회 공개자료를 같은 단위로 정리해 브랜드 창업비용, 가맹점 변화, 업종 중앙값을 비교하고 내 점포 조건으로 계산합니다.',canonical:'/',schemas:[orgSchema,siteSchema]})}<main id="main" data-v10-home="1"><section class="home-intro"><div class="shell"><h1>프랜차이즈 창업,<br>숫자로 먼저 비교하세요</h1><p>브랜드별 창업비용, 가맹점 변화, 업종 중앙값과 공개 매출지표를 같은 기준으로 비교하고 내 점포 조건을 계산합니다.</p><form class="home-search" action="${url('/brands/')}" method="get"><input name="q" aria-label="브랜드명 또는 업종 검색" placeholder="브랜드명 또는 업종 검색"><button>검색</button></form><div class="quick-links"><a href="${url('/brands/')}">브랜드 찾기</a><a href="${url('/compare/')}">두 브랜드 비교</a><a href="${url('/tools/startup-cost/')}">창업비용 계산</a><a href="${url('/categories/')}">업종별 보기</a></div></div></section><div class="shell data-status"><div><b>${official.records.length.toLocaleString('ko-KR')}</b><span>공식 원본 레코드</span></div><div><b>${matched.matches.length}</b><span>카탈로그 공식 매칭</span></div><div><b>${categoryEntries.length}</b><span>분석 업종</span></div><div><b>9</b><span>계산·분석 도구</span></div><div><b>${reviewDate}</b><span>데이터 갱신일</span></div></div><section class="home-section"><div class="shell"><div class="section-head"><h2>대표 브랜드 데이터</h2><a href="${url('/brands/')}">170개 브랜드 찾기</a></div><p class="scroll-hint">표는 옆으로 밀어 확인할 수 있습니다.</p><div class="table-scroll"><table class="data-table directory-table"><thead><tr><th>브랜드</th><th>업종</th><th class="num">공개 창업비용</th><th class="num">가맹점</th><th class="num">전년 증감</th></tr></thead><tbody>${homeFeatured.map(b=>`<tr><td><a href="${url(`/brands/${slugOf(b)}/`)}">${esc(b.name)}</a></td><td>${esc(b.category)}</td><td class="num">${won(b.cost)}</td><td class="num">${count(b.stores)}</td><td class="num ${finite(growthPct(b))?(growthPct(b)>=0?'positive':'negative'):''}">${pct(growthPct(b))}</td></tr>`).join('')}</tbody></table></div></div></section><section class="home-section"><div class="shell"><div class="section-head"><h2>업종별 공개 창업비용 중앙값</h2><a href="${url('/categories/')}">업종 데이터 보기</a></div><div class="chart-panel">${renderHorizontalBars(categoryChartData,{title:'업종별 공개 창업비용 중앙값',desc:'공식 매칭된 카탈로그 브랜드의 2025년 공개 창업비용 중앙값',unit:'만원'})}<div class="chart-legend">공식 매칭된 카탈로그 브랜드의 중앙값이며, 실제 총투자금이나 추천 순위가 아닙니다.</div></div></div></section><section class="home-section"><div class="shell"><div class="section-head"><h2>바로 쓰는 도구</h2></div><div class="feature-list"><a href="${url('/tools/startup-cost/')}"><strong>창업비용 계산</strong><span>공개합계에 임대·권리금·추가공사를 분리해 더합니다.</span></a><a href="${url('/tools/monthly-profit-simulator/')}"><strong>월 손익 계산</strong><span>매출과 비용 가정으로 단순 영업잔액을 계산합니다.</span></a><a href="${url('/tools/brand-filter/')}"><strong>조건으로 브랜드 찾기</strong><span>업종·비용·점포 규모·증감 조건으로 좁힙니다.</span></a><a href="${url('/areas/')}"><strong>지역 데이터</strong><span>점포 수와 밀도를 추천 점수 없이 비교합니다.</span></a></div></div></section><section class="home-section"><div class="shell"><div class="section-head"><h2>데이터 리포트</h2></div><div class="report-grid"><a href="${url('/guide/low-price-coffee/')}"><strong>저가커피 브랜드 데이터 비교</strong><span>메가MGC·컴포즈·빽다방·더벤티의 공식값과 점포 흐름</span></a><a href="${url('/guides/how-to-read-franchise-disclosure/')}"><strong>정보공개서 보는 순서</strong><span>창업비용보다 먼저 확인할 점포·계약 숫자</span></a><a href="${url('/guides/why-rent-deposit-is-not-in-startup-cost/')}"><strong>공개 창업비용에 빠지는 돈</strong><span>임대보증금·권리금·운전자금을 분리하는 이유</span></a></div></div></section></main>${end()}`;
await write('',homeHtml);

// DIRECTORY
const catOptions=categoryEntries.map(([s,c])=>`<option value="${esc(s)}">${esc(c.name)}</option>`).join('');
const directoryRows=views.map(b=>{const g=growthPct(b);return `<tr data-name="${esc(b.name.toLowerCase())}" data-cat="${esc(b.categorySlug)}" data-cost="${finite(b.cost)?b.cost:''}" data-stores="${finite(b.stores)?b.stores:''}" data-growth="${finite(g)?g:''}"><td><a href="${url(`/brands/${slugOf(b)}/`)}">${esc(b.name)}</a>${priorityCandidates.has(b.name)?' <span class="pill">분석 페이지</span>':''}</td><td>${esc(b.category)}</td><td class="num">${won(b.cost)}</td><td class="num">${count(b.stores)}</td><td class="num ${finite(g)?g>=0?'positive':'negative':''}">${pct(g)}</td><td>${b.official?.referenceYear??'정보 없음'}</td></tr>`}).join('');
await write('brands',`${head({title:'프랜차이즈 브랜드 찾기 | 창업비용·가맹점 필터',description:'170개 프랜차이즈 브랜드를 업종, 공개 창업비용, 가맹점 수, 전년 점포 변화로 찾습니다. 미매칭 값은 0으로 채우지 않습니다.',canonical:'/brands/',schemas:[breadcrumbSchema([['홈','/'],['브랜드 찾기','/brands/']])]})}<main id="main" data-v10-directory="1"><div class="shell page">${crumb([['홈','/'],['브랜드 찾기','/brands/']])}<div class="page-head"><h1>프랜차이즈 브랜드 찾기</h1><p>공식 레코드가 확인된 브랜드만 숫자를 표시합니다. 검색·필터 결과 URL은 정식 공개 시 색인하지 않습니다.</p></div><div class="directory-controls"><label class="wide">브랜드 검색<input id="directorySearch" placeholder="브랜드명"></label><label>업종<select id="directoryCategory"><option value="all">전체 업종</option>${catOptions}</select></label><label>최대 공개비용<select id="directoryCost"><option value="">제한 없음</option><option value="5000">5,000만원</option><option value="10000">1억원</option><option value="15000">1억5,000만원</option><option value="20000">2억원</option></select></label><label>최소 가맹점<select id="directoryStores"><option value="">제한 없음</option><option value="100">100개</option><option value="500">500개</option><option value="1000">1,000개</option></select></label><label>점포 변화<select id="directoryGrowth"><option value="all">전체</option><option value="up">증가</option><option value="down">감소</option></select></label><label>정렬<select id="directorySort"><option value="name">브랜드명</option><option value="costAsc">비용 낮은순</option><option value="storesDesc">가맹점 많은순</option><option value="growthDesc">증감률 높은순</option></select></label></div><section data-v10-directory><div class="directory-summary"><b id="directoryCount">170개 브랜드</b><span>공식 매칭 ${matched.matches.length} · 미매칭 ${matched.unmatched.length} · 확인 필요 ${matched.ambiguous.length}</span></div><p class="scroll-hint">표는 옆으로 밀어 확인할 수 있습니다.</p><div class="table-scroll"><table class="data-table directory-table" id="directoryTable"><thead><tr><th>브랜드</th><th>업종</th><th class="num">공개비용</th><th class="num">가맹점</th><th class="num">전년 증감</th><th>기준연도</th></tr></thead><tbody>${directoryRows}</tbody></table></div></section><div class="callout source"><strong>데이터 처리 원칙</strong><p>공식 명칭을 확인하지 못한 브랜드는 기존 샘플값을 재사용하지 않습니다. 누락값은 “정보 없음”으로 유지합니다.</p></div></div></main>${end()}`);

// BRAND PAGES
for(const b of views){
  const candidate=priorityCandidates.has(b.name),s=catStats(b.categorySlug),g=growthPct(b),abs=growthAbs(b),cg=finite(b.cost)&&finite(s.cost)?(b.cost-s.cost)/s.cost*100:null,storePeer=finite(b.stores)&&finite(s.stores)?(b.stores-s.stores)/s.stores*100:null,salesPeer=finite(b.sales)&&finite(s.sales)?(b.sales-s.sales)/s.sales*100:null,faqs=brandFaq(b),comps=costComponents(b),history=b.official?.storeHistory||[],peerList=peers(b).sort((a,z)=>Math.abs((a.cost??0)-(b.cost??0))-Math.abs((z.cost??0)-(b.cost??0))).slice(0,3);
  const answer=b.official?`${b.name}의 ${b.official.referenceYear} 정보공개서 공개 창업비용은 ${won(b.cost)}입니다. 이 합계는 임대보증금·권리금·철거·전기증설 등 점포별 비용 전체를 뜻하지 않습니다.`:`${b.name}은 현재 공식 데이터와의 명칭 매칭을 검토 중입니다. 확인되지 않은 비용·가맹점 수를 추정하거나 기존 샘플값으로 채우지 않습니다.`;
  const costChart=comps.length?renderStackedBar(comps,{title:`${b.name} 공개 창업비용 구성`,desc:`${b.official?.referenceYear??''} 공개비용 항목별 구성`}):'';
  const storeChart=history.length>=2?renderLineChart(history.map(r=>({label:String(r.year),value:r.stores})),{title:`${b.name} 가맹점 추이`,desc:'정보공개서 연도별 가맹점 수',unit:'개'}):'';
  const benchmark=[{label:'공개 창업비용',value:b.cost,peer:s.cost,unit:'만원'},{label:'가맹점 수',value:b.stores,peer:s.stores,unit:'개'},{label:'평균매출 공개지표',value:b.sales,peer:s.sales,unit:'만원/년'}].filter(x=>finite(x.value)&&finite(x.peer));
  const benchmarkHtml=benchmark.map(x=>{const mx=Math.max(Number(x.value),Number(x.peer),1),a=Number(x.value)/mx*100,p=Number(x.peer)/mx*100;return `<div class="chart-panel"><h3>${esc(x.label)}</h3><div class="definition-list"><div><dt>${esc(b.name)}</dt><dd>${x.unit==='개'?count(x.value):won(x.value)}</dd></div><div><dt>${esc(b.category)} 중앙값</dt><dd>${x.unit==='개'?count(x.peer):won(x.peer)}</dd></div></div><div aria-hidden="true" style="margin-top:10px"><div style="height:12px;background:#EEE8DE"><span style="display:block;width:${a.toFixed(1)}%;height:100%;background:#2457D6"></span></div><div style="height:12px;background:#EEE8DE;margin-top:5px"><span style="display:block;width:${p.toFixed(1)}%;height:100%;background:#8B847C"></span></div></div></div>`}).join('');
  const qa=faqs.map(([q1,a])=>`<details><summary>${esc(q1)}</summary><p>${esc(a)}</p></details>`).join('');
  const schemas=[breadcrumbSchema([['홈','/'],['브랜드 찾기','/brands/'],[b.name,`/brands/${slugOf(b)}/`]]),{'@context':'https://schema.org','@type':'Dataset','name':`${b.name} 프랜차이즈 공개 데이터`,'description':answer,'url':absolute(`/brands/${slugOf(b)}/`),'dateModified':reviewDate,'creator':{'@type':'Organization','name':'창업데이터랩'},'isBasedOn':b.official?.sourceUrl||'https://www.data.go.kr/'}];
  if(faqs.length>=3)schemas.push({'@context':'https://schema.org','@type':'FAQPage','mainEntity':faqs.map(([q1,a])=>({'@type':'Question','name':q1,'acceptedAnswer':{'@type':'Answer','text':a}}))});
  const title=candidate&&b.official?`${b.name} 창업비용·가맹점·매출 공개지표 | 창업데이터랩`:`${b.name} 프랜차이즈 데이터 | 창업데이터랩`;
  const description=b.official?`${b.name} ${b.official.referenceYear}년 공개 창업비용 ${won(b.cost)}, 가맹점 ${count(b.stores)}를 업종 중앙값·점포 변화와 함께 확인합니다.`:`${b.name} 공식 데이터 매칭 상태와 출처 확인 현황을 제공합니다. 확인되지 않은 값은 추정하지 않습니다.`;
  const page=`${head({title,description,canonical:`/brands/${slugOf(b)}/`,schemas})}<main id="main" data-v10-brand="1" data-quality-score="${b.quality.score}" data-index-candidate="${candidate?'1':'0'}"><div class="shell page">${crumb([['홈','/'],['브랜드 찾기','/brands/'],[b.name,`/brands/${slugOf(b)}/`]])}<article><header class="brand-header"><div class="brand-header-main"><div><div class="brand-category">${esc(b.category)}</div><h1>${esc(b.name)}</h1><div class="meta-line"><span><b>정보공개서 기준</b> ${b.official?.referenceYear??'정보 없음'}</span><span><b>이전 비교 기준</b> ${b.official?.previousReferenceYear??'정보 없음'}</span><span><b>데이터 갱신</b> ${reviewDate}</span></div></div><div class="brand-actions"><a class="button" href="${url(`/tools/startup-cost/?brand=${encodeURIComponent(slugOf(b))}`)}">내 조건으로 계산</a><a class="button secondary" href="${url('/compare/')}">다른 브랜드와 비교</a></div></div><div class="brand-toc"><nav><a href="#answer">한줄 답</a><a href="#cost">비용 구성</a><a href="#stores">점포 변화</a><a href="#benchmark">업종 비교</a><a href="#check">추가 확인</a><a href="#source">출처</a></nav></div></header><section id="answer" class="block" style="margin-top:34px"><div class="answer-box"><strong>한줄 답</strong><p>${esc(answer)}</p></div><div class="stat-grid"><div class="stat-card"><span class="label">공개 창업비용</span><b class="value">${won(b.cost)}</b><small>${b.official?.referenceYear??'기준연도 미확인'} · 공식 공개합계</small></div><div class="stat-card"><span class="label">가맹점 수</span><b class="value">${count(b.stores)}</b><small>${b.official?.referenceYear??'기준연도 미확인'} 실적</small></div><div class="stat-card"><span class="label">평균매출 공개지표</span><b class="value">${won(b.sales)}</b><small>연간 공개값 · 매출은 이익이 아닙니다</small></div><div class="stat-card"><span class="label">전년 점포 변화</span><b class="value ${finite(g)?g>=0?'positive':'negative':''}">${pct(g)}</b><small>${finite(abs)?`${abs>=0?'+':''}${Math.round(abs).toLocaleString('ko-KR')}개`: '비교값 정보 없음'}</small></div></div><div class="callout warning"><strong>공개합계 ≠ 실제 총투자금</strong><p>정보공개서 합계에는 점포 임대보증금·권리금·철거·전기증설·외부공사·초기 운전자금이 빠질 수 있습니다. VAT 포함 여부와 기준면적은 현재 정규화 데이터에 충분히 포함되지 않아 원문 확인이 필요합니다.</p></div><div class="editorial-summary"><h2>30초 데이터 요약</h2><p>${esc(summaryText(b))}</p></div></section>${b.official?`<section class="block" id="cost"><h2>${esc(b.name)} 공개 창업비용은 어떻게 구성되나요?</h2><p>공개 합계의 항목별 비중을 한 번만 시각화합니다. 인테리어 항목이 별도 필드로 제공되지 않은 경우 “기타” 안에 포함될 수 있으므로 원문 항목 정의를 확인해야 합니다.</p>${costChart||'<p class="note">구성비를 계산할 세부항목이 충분하지 않습니다.</p>'}${comps.length?`<details class="chart-data"><summary>차트 수치 표로 보기</summary>${costTable(b)}</details>`:''}</section><section class="block" id="stores"><h2>${esc(b.name)} 가맹점은 어떻게 변했나요?</h2><p>점포 수가 많거나 늘었다는 사실만으로 개별 점포 수익을 판단하지 않습니다. 신규점·계약종료·계약해지를 같이 봅니다.</p>${storeChart||'<p class="note">비교 가능한 연도별 점포 데이터가 충분하지 않습니다.</p>'}${history.length?`<details class="chart-data"><summary>연도별 수치 표로 보기</summary><table class="data-table stack-mobile"><thead><tr><th>연도</th><th class="num">가맹점</th><th class="num">신규</th><th class="num">계약종료</th><th class="num">계약해지</th></tr></thead><tbody>${history.map(r=>`<tr><td data-label="연도">${r.year}</td><td data-label="가맹점" class="num">${count(r.stores)}</td><td data-label="신규" class="num">${count(r.newStores)}</td><td data-label="계약종료" class="num">${count(r.contractEnd)}</td><td data-label="계약해지" class="num">${count(r.contractCancel)}</td></tr>`).join('')}</tbody></table></details>`:''}<div class="definition-list" style="margin-top:18px"><div><dt>현재 신규 가맹점</dt><dd>${count(b.official.newStores)}</dd></div><div><dt>계약 종료</dt><dd>${count(b.official.contractEnd)}</dd></div><div><dt>계약 해지</dt><dd>${count(b.official.contractCancel)}</dd></div></div></section><section class="block" id="benchmark"><h2>${esc(b.category)} 업종 중앙값과 어디가 다른가요?</h2><p>같은 카탈로그 업종에서 공식 매칭된 브랜드의 중앙값과 비교합니다. 중앙값보다 높거나 낮다는 사실은 추천 점수가 아닙니다.</p>${benchmarkHtml}${finite(cg)||finite(storePeer)||finite(salesPeer)?`<div class="definition-list" style="margin-top:20px">${finite(cg)?`<div><dt>공개비용 중앙값 대비</dt><dd>${pct(cg)}</dd></div>`:''}${finite(storePeer)?`<div><dt>가맹점 중앙값 대비</dt><dd>${pct(storePeer)}</dd></div>`:''}${finite(salesPeer)?`<div><dt>평균매출 공개지표 중앙값 대비</dt><dd>${pct(salesPeer)}</dd></div>`:''}</div>`:''}</section>`:''}<section class="block" id="check"><h2>계약 전에 무엇을 추가로 검사해야 하나요?</h2><p>${b.official?'공개자료는 본사 관련 표준비용과 과거 실적을 비교하는 출발점입니다. 실제 점포의 임대조건과 공사 범위가 달라지면 총 준비자금과 월 비용 구조도 달라집니다.':'공식 명칭 매칭이 완료되기 전에는 비용 비교에 이 브랜드를 사용하지 않는 것이 안전합니다.'}</p>${hiddenCostChecklist()}</section>${peerList.length?`<section class="block"><h2>같은 업종에서 함께 볼 브랜드</h2><div class="peer-links">${peerList.map(p=>`<a href="${url(`/brands/${slugOf(p)}/`)}"><strong>${esc(p.name)}</strong><span>공개비용 ${won(p.cost)} · 가맹점 ${count(p.stores)}</span></a>`).join('')}</div></section>`:''}<section class="block"><h2>자주 묻는 질문</h2><div class="faq">${qa}</div></section><section class="block" id="source"><h2>출처와 계산 기준</h2><div class="source-box"><p><strong>1차 출처</strong> ${sourceLink()}</p><p><strong>기준연도</strong> ${b.official?.referenceYear??'정보 없음'}</p><p><strong>데이터 갱신</strong> ${reviewDate}</p><p><strong>품질점수</strong> ${b.quality.score}/100 · ${candidate?'정식 공개 시 색인 후보':'정식 공개 시 기본 noindex 후보'}</p><p><strong>누락값</strong> 0으로 대체하지 않습니다.</p></div></section></article></div></main>${end()}`;
  await write(`brands/${slugOf(b)}`,page);
}

// CATEGORY PAGES + HUB
const catCards=categoryEntries.map(([slug,c])=>{const s=catStats(slug);return `<a href="${url(`/categories/${slug}/`)}"><strong>${esc(c.name)}</strong><span>공식 매칭 ${s.rows.length}개 · 공개비용 중앙값 ${won(s.cost)}</span></a>`}).join('');
await write('categories',`${head({title:'프랜차이즈 업종 데이터 | 창업비용 중앙값·가맹점 비교',description:'카페, 치킨, 편의점 등 20개 업종의 공식 매칭 브랜드 수와 창업비용·가맹점 중앙값을 비교합니다.',canonical:'/categories/',schemas:[breadcrumbSchema([['홈','/'],['업종 데이터','/categories/']])]})}<main id="main"><div class="shell page">${crumb([['홈','/'],['업종 데이터','/categories/']])}<div class="page-head"><h1>업종 데이터</h1><p>업종별 중앙값은 추천 순위가 아니라 브랜드 간 공개값의 위치를 읽기 위한 기준선입니다.</p></div><div class="report-grid">${catCards}</div></div></main>${end()}`);
for(const [slug,c] of categoryEntries){const s=catStats(slug),rows=s.rows.sort((a,b)=>(a.cost??Infinity)-(b.cost??Infinity)),chart=renderHorizontalBars(rows.filter(b=>finite(b.cost)).slice(0,16).map(b=>({label:b.name,value:b.cost})),{title:`${c.name} 브랜드 공개 창업비용`,desc:`${c.name} 공식 매칭 브랜드 공개비용 비교`,unit:'만원'});const schema={'@context':'https://schema.org','@type':'Dataset','name':`${c.name} 프랜차이즈 공개 데이터`,'description':`${c.name} 브랜드 창업비용·가맹점·점포 변화 통계`,'url':absolute(`/categories/${slug}/`),'dateModified':reviewDate,'creator':{'@type':'Organization','name':'창업데이터랩'}};await write(`categories/${slug}`,`${head({title:`${c.name} 프랜차이즈 창업비용·가맹점 비교 | 창업데이터랩`,description:`${c.name} 공식 매칭 ${s.rows.length}개 브랜드의 공개 창업비용 중앙값 ${won(s.cost)}, 가맹점 중앙값 ${count(s.stores)}를 비교합니다.`,canonical:`/categories/${slug}/`,schemas:[breadcrumbSchema([['홈','/'],['업종 데이터','/categories/'],[c.name,`/categories/${slug}/`]]),schema]})}<main id="main" data-v10-category="1"><div class="shell page">${crumb([['홈','/'],['업종 데이터','/categories/'],[c.name,`/categories/${slug}/`]])}<div class="page-head"><h1>${esc(c.name)} 프랜차이즈 데이터</h1><p>${esc(c.name)} 브랜드의 공개 창업비용·가맹점·평균매출 공개지표를 동일 카탈로그 기준으로 비교합니다.</p></div><div class="stat-grid"><div class="stat-card"><span class="label">공식 매칭 브랜드</span><b class="value">${s.rows.length}개</b><small>카탈로그 내 공식 레코드 매칭</small></div><div class="stat-card"><span class="label">공개 창업비용 중앙값</span><b class="value">${won(s.cost)}</b><small>${official.referenceYear} 기준</small></div><div class="stat-card"><span class="label">가맹점 중앙값</span><b class="value">${count(s.stores)}</b><small>브랜드별 가맹점 수 중앙값</small></div><div class="stat-card"><span class="label">점포 증감 중앙값</span><b class="value">${pct(s.growth)}</b><small>이전 기준 대비</small></div></div><section class="block"><h2>${esc(c.name)} 브랜드별 공개 창업비용</h2>${chart}<details class="chart-data"><summary>전체 수치 표로 보기</summary><p class="scroll-hint">표는 옆으로 밀어 확인할 수 있습니다.</p><div class="table-scroll"><table class="data-table directory-table"><thead><tr><th>브랜드</th><th class="num">공개비용</th><th class="num">가맹점</th><th class="num">증감</th><th class="num">평균매출 공개지표</th></tr></thead><tbody>${rows.map(b=>`<tr><td><a href="${url(`/brands/${slugOf(b)}/`)}">${esc(b.name)}</a></td><td class="num">${won(b.cost)}</td><td class="num">${count(b.stores)}</td><td class="num">${pct(growthPct(b))}</td><td class="num">${won(b.sales)}</td></tr>`).join('')}</tbody></table></div></details></section><div class="callout warning"><strong>중앙값은 추천 점수가 아닙니다</strong><p>비용이 낮거나 가맹점이 많다는 사실만으로 내 점포의 수익성·안전성을 판단할 수 없습니다. 점포 임대조건과 비용구조를 계산기에 따로 넣어야 합니다.</p></div></div></main>${end()}`)}

