const compareLinks=[];
for(const [aName,bName] of CURATED_COMPARE_NAMES){const a=byName.get(aName),b=byName.get(bName);if(!a||!b)continue;const route=`/compare/${slugOf(a)}-vs-${slugOf(b)}/`,oldRel=`compare/${slugOf(a)}/${slugOf(b)}`,newRel=`compare/${slugOf(a)}-vs-${slugOf(b)}`;compareLinks.push({a,b,route});const sameYear=a.official?.referenceYear&&b.official?.referenceYear&&Number(a.official.referenceYear)===Number(b.official.referenceYear),costDiff=finite(a.cost)&&finite(b.cost)?a.cost-b.cost:null,storeDiff=finite(a.stores)&&finite(b.stores)?a.stores-b.stores:null,gA=growthPct(a),gB=growthPct(b),growthDiff=finite(gA)&&finite(gB)?gA-gB:null;const answer=a.official&&b.official?`${aName}와 ${bName}의 공개비용 차이는 ${signedWon(costDiff)}, 가맹점 수 차이는 ${finite(storeDiff)?`${storeDiff>0?'+':''}${Math.round(storeDiff).toLocaleString('ko-KR')}개`:'정보 없음'}입니다. 어느 쪽이 더 적합한지는 점포 임대·인건비·공사비 조건을 함께 봐야 합니다.`:`두 브랜드 중 공식 매칭이 완료되지 않은 항목은 비교값을 표시하지 않습니다.`;const rows=[['가맹비',a.fee,b.fee,'공개 계약 관련 비용'],['교육비',a.education,b.education,'교육 범위·대상 확인'],['보증금',a.deposit,b.deposit,'가맹 보증금은 임대보증금과 다름'],['기타 공개비용',a.other,b.other,'설비·공사 포함 범위 원문 확인'],['공개 창업비용 합계',a.cost,b.cost,'실제 총투자금과 다를 수 있음'],['가맹점 수',a.stores,b.stores,'브랜드 규모이며 수익 아님'],['전년 증감률',gA,gB,'한 해 변화만으로 성장성 단정 금지'],['평균매출 공개지표',a.sales,b.sales,'매출은 이익이 아님']];const desktopRows=rows.map(([label,av,bv,meaning])=>`<tr><td>${esc(label)}</td><td class="num">${label.includes('가맹점')?count(av):label.includes('증감')?pct(av):won(av)}</td><td class="num">${label.includes('가맹점')?count(bv):label.includes('증감')?pct(bv):won(bv)}</td><td class="meaning">${esc(meaning)}</td></tr>`).join('');const mobileRows=rows.map(([label,av,bv,meaning])=>`<article><h3>${esc(label)}</h3><dl><div><dt>${esc(aName)}</dt><dd>${label.includes('가맹점')?count(av):label.includes('증감')?pct(av):won(av)}</dd></div><div><dt>${esc(bName)}</dt><dd>${label.includes('가맹점')?count(bv):label.includes('증감')?pct(bv):won(bv)}</dd></div></dl><p class="note">${esc(meaning)}</p></article>`).join('');const costChart=renderGroupedBars([['가맹비',a.fee,b.fee],['교육비',a.education,b.education],['보증금',a.deposit,b.deposit],['기타',a.other,b.other],['공개합계',a.cost,b.cost]].map(([label,av,bv])=>({label,a:av,b:bv})),{title:`${aName}와 ${bName} 공개 창업비용 비교`,desc:'두 브랜드 공개비용 구성 항목 비교',aLabel:aName,bLabel:bName,unit:'만원'});const aHist=a.official?.storeHistory||[],bHist=b.official?.storeHistory||[],years=[...new Set([...aHist.map(x=>x.year),...bHist.map(x=>x.year)])].sort();const trendRows=years.map(y=>({label:String(y),a:aHist.find(x=>x.year===y)?.stores,b:bHist.find(x=>x.year===y)?.stores}));const trendChart=renderGroupedBars(trendRows,{title:`${aName}와 ${bName} 가맹점 추이`,desc:'연도별 가맹점 수 비교',aLabel:aName,bLabel:bName,unit:'개'});const schemas=[breadcrumbSchema([['홈','/'],['두 브랜드 비교','/compare/'],[`${aName} vs ${bName}`,route]]),{'@context':'https://schema.org','@type':'Dataset','name':`${aName} vs ${bName} 프랜차이즈 비교 데이터`,'description':answer,'url':absolute(route),'dateModified':reviewDate}];const page=`${head({title:`${aName} vs ${bName} 창업비용·가맹점 비교 | 창업데이터랩`,description:`${aName}와 ${bName}의 공개 창업비용·가맹점·점포 증감을 동일 기준으로 비교하고 차이가 의미하는 확인사항을 정리합니다.`,canonical:route,schemas})}<main id="main" data-v10-compare="1"><div class="shell page">${crumb([['홈','/'],['두 브랜드 비교','/compare/'],[`${aName} vs ${bName}`,route]])}<article><header class="compare-head"><h1>${esc(aName)} vs ${esc(bName)}</h1><div class="answer-box"><strong>한줄 답</strong><p>${esc(answer)}</p></div>${!sameYear?`<div class="callout danger"><strong>비교 기준연도 확인 필요</strong><p>두 브랜드의 공개 데이터 기준연도가 다릅니다. 각 숫자 옆의 기준연도를 확인하세요.</p></div>`:''}<div class="compare-brand-bar"><div class="compare-brand"><strong>${esc(aName)}</strong><span>${esc(a.category)} · ${a.official?.referenceYear??'연도 미확인'}</span></div><div class="divider"></div><div class="compare-brand"><strong>${esc(bName)}</strong><span>${esc(b.category)} · ${b.official?.referenceYear??'연도 미확인'}</span></div></div><div class="compare-diff"><div><span>공개비용 차이 · A-B</span><b>${signedWon(costDiff)}</b></div><div><span>가맹점 차이 · A-B</span><b>${finite(storeDiff)?`${storeDiff>0?'+':''}${Math.round(storeDiff).toLocaleString('ko-KR')}개`:'정보 없음'}</b></div><div><span>증감률 차이 · A-B</span><b>${finite(growthDiff)?`${growthDiff>0?'+':''}${growthDiff.toFixed(1)}%p`:'정보 없음'}</b></div></div></header><section class="block"><h2>공개 창업비용 항목은 어떻게 다른가요?</h2>${costChart}<div class="compare-table-desktop"><p class="scroll-hint">표는 옆으로 밀어 확인할 수 있습니다.</p><div class="table-scroll"><table class="data-table compare-table"><thead><tr><th>항목</th><th class="num">${esc(aName)}</th><th class="num">${esc(bName)}</th><th>차이·의미</th></tr></thead><tbody>${desktopRows}</tbody></table></div></div><div class="mobile-compare">${mobileRows}</div></section>${trendRows.length>=2?`<section class="block"><h2>가맹점 흐름은 어떻게 달랐나요?</h2>${trendChart}<p class="note">점포 수 증감은 과거 공개실적이며 내 점포의 수익을 예측하지 않습니다.</p></section>`:''}<section class="block"><h2>이 비교가 틀릴 수 있는 조건</h2><div class="callout warning"><p>기준면적, VAT 포함 여부, 별도공사 범위, 점포 임대보증금·권리금, 프로모션 적용 여부가 다르면 총 투자금 비교가 달라집니다. 공개비용이 낮다는 이유만으로 더 유리한 브랜드라고 판단하지 않습니다.</p></div></section><div class="actions"><a class="button" href="${url(`/tools/startup-cost/?brand=${encodeURIComponent(slugOf(a))}`)}">${esc(aName)} 내 조건 계산</a><a class="button secondary" href="${url('/compare/')}">다른 브랜드 비교</a></div><section class="block"><h2>출처</h2><div class="source-box"><p>${sourceLink()}</p><p>데이터 갱신 ${reviewDate}</p></div></section></article></div></main>${end()}`;await write(newRel,page);await write(oldRel,`${head({title:`${aName} vs ${bName} 비교 주소 안내 | 창업데이터랩`,description:'비교 페이지의 새 주소를 안내합니다.',canonical:route})}<main><div class="shell page"><h1>비교 페이지 주소가 정리되었습니다</h1><p><a href="${url(route)}">${esc(aName)} vs ${esc(bName)} 비교 보기</a></p></div></main>${end()}`)}
await write('compare',`${head({title:'프랜차이즈 브랜드 비교 | 대표 비교 조합',description:'같은 업종의 대표 브랜드 비교 10개를 공식 공개비용·가맹점·점포 변화 기준으로 나란히 확인합니다.',canonical:'/compare/',schemas:[breadcrumbSchema([['홈','/'],['두 브랜드 비교','/compare/']])]})}<main id="main"><div class="shell page">${crumb([['홈','/'],['두 브랜드 비교','/compare/']])}<div class="page-head"><h1>두 브랜드 비교</h1><p>검색 수요와 같은 업종 비교 가치가 명확한 대표 조합만 정적 페이지로 제공합니다. 모든 조합을 14,000개 이상 자동 생성하지 않습니다.</p></div><div class="report-grid">${compareLinks.map(({a,b,route})=>`<a href="${url(route)}"><strong>${esc(a.name)} vs ${esc(b.name)}</strong><span>공개비용·가맹점·점포 변화 비교</span></a>`).join('')}</div></div></main>${end()}`);

// STARTUP COST CALCULATOR
